gaps_out, asm_out = [], []
for g in gaps:
    gaps_out.append({
        "id": C + str(g["n"]), "title": g["title"], "source": g["source"], "section": g["section"],
        "description": g["description"], "evidence": g["evidence"], "type": g["type"], "area": g["area"],
        "severity": g["severity"], "needed_by_wave": g["needed_by_wave"], "legacy_ref": g["legacy_ref"],
        "owner_role": g["owner_role"], "asm": A + str(g["n"]), "proposed": g["proposed"], "wp": WP,
    })
for a in assumptions:
    asm_out.append({
        "id": A + str(a["n"]), "text": a["text"], "why": a["why"], "read": a["read"],
        "gap": (C + str(a["gap"]) if a["gap"] else ""), "applied_in": a["applied_in"],
        "confidence": "Medium", "confirm": a["confirm"], "impact": a["impact"], "wp": WP,
    })

for kind, rows in (("gaps", gaps_out), ("assumptions", asm_out)):
    p = ROOT / "_work" / "msr" / kind / f"{WP}.jsonl"
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("w", encoding="utf-8", newline="\n") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(kind, len(rows), "rows ->", p)
